def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count positive integers in ``[start, finish]`` ending in ``s`` whose
    digits are all at most ``limit``.

    The fixed suffix leaves only a (possibly empty) digit prefix to count.
    Counting prefixes by length and using a digit bound avoids iterating over
    the potentially very large input range.
    """
    if start > finish or finish < 1:
        return 0
    if not s or not s.isdigit():
        raise ValueError("s must be a non-empty string of decimal digits")
    if not 1 <= limit <= 9:
        raise ValueError("limit must be between 1 and 9")

    # Every matching integer contains these suffix digits, so one disallowed
    # suffix digit makes the answer zero.
    if any(int(digit) > limit for digit in s):
        return 0

    suffix_length = len(s)

    def all_prefixes(prefix_length: int) -> int:
        """Count positive, fixed-width prefixes with digits in [0, limit]."""
        if prefix_length == 0:
            return 1
        return limit * (limit + 1) ** (prefix_length - 1)

    def prefixes_less_than(bound: str) -> int:
        """Count valid fixed-width prefixes lexicographically below bound."""
        total = 0
        width = len(bound)
        for index, character in enumerate(bound):
            bound_digit = int(character)
            min_digit = 1 if index == 0 else 0
            choices = max(0, min(limit, bound_digit - 1) - min_digit + 1)
            if choices:
                total += choices * (limit + 1) ** (width - index - 1)

            # The bound itself is no longer a valid continuation; the smaller
            # prefixes counted above are still valid.
            if bound_digit < min_digit or bound_digit > limit:
                return total
        # The loop's branches count smaller values only (not the bound itself).
        return total

    def prefix_is_valid(prefix: str) -> bool:
        return bool(prefix) and prefix[0] != "0" and all(
            int(digit) <= limit for digit in prefix
        )

    def count_at_most(number: int) -> int:
        if number < 1:
            return 0
        bound = str(number)
        bound_length = len(bound)
        if suffix_length > bound_length:
            return 0

        total = 0
        # All shorter numbers are automatically below number.
        for length in range(suffix_length, bound_length):
            prefix_length = length - suffix_length
            if prefix_length == 0:
                # An integer's ordinary decimal representation cannot start
                # with zero, even if the supplied suffix string does.
                if s[0] != "0":
                    total += 1
            else:
                total += all_prefixes(prefix_length)

        prefix_length = bound_length - suffix_length
        if prefix_length == 0:
            # The only number of this length with this suffix is s itself.
            if s[0] != "0" and int(s) <= number:
                total += 1
            return total

        prefix_bound = bound[:prefix_length]
        suffix_bound = bound[prefix_length:]
        total += prefixes_less_than(prefix_bound)
        if s <= suffix_bound and prefix_is_valid(prefix_bound):
            total += 1
        return total

    return count_at_most(finish) - count_at_most(start - 1)
